<script setup lang="ts">
import {ref,onUnmounted} from 'vue';import {call} from './api';import {jobContract as c} from './job-contract';
type Row={job_id:string;document_id:string;state:string;attempts:number;error:string|null;result:string|null;verified_at:string|null};
const resource=ref(''),rows=ref<Row[]>([]),busy=ref(false),error=ref('');let epoch=0;onUnmounted(()=>{epoch++});function reset(){epoch++;rows.value=[];busy.value=false;error.value='';}async function refresh(){const run=++epoch;busy.value=true;error.value='';try{const result=await call<{items:Row[]}>(c.path+'/results',{resourceId:resource.value});if(!Array.isArray(result?.items))throw Error();if(run===epoch)rows.value=result.items;}catch{if(run===epoch){rows.value=[];error.value='Job results unavailable or access denied';}}finally{if(run===epoch)busy.value=false;}}
</script>
<template><section aria-label="Background integrity jobs" class="job-panel"><h2>Document integrity jobs</h2><form @submit.prevent="refresh"><label>Job resource<input v-model="resource" @input="reset" maxlength="128" /></label><button :disabled="busy">Refresh jobs</button></form><p v-if="busy" role="status">Loading jobs</p><p v-if="error" role="alert">{{error}}</p><p v-if="!busy&&!error&&!rows.length">No job results loaded</p><ul aria-label="Integrity job results"><li v-for="r in rows" :key="r.job_id"><code>{{r.document_id}}</code> — {{r.state}} {{r.result}} — {{r.attempts}} attempts <span v-if="r.error">{{r.error}}</span><time v-if="r.verified_at">{{r.verified_at}}</time></li></ul></section></template>
<style scoped>.job-panel{margin-top:2rem;border-top:1px solid;padding-top:1rem}form{display:flex;gap:1rem;flex-wrap:wrap}label{display:flex;flex-direction:column}li{margin:1rem 0;overflow-wrap:anywhere}time{display:block}button:focus-visible,input:focus-visible{outline:3px solid #185abc;outline-offset:2px}@media(max-width:40rem){form>*{flex:1 1 100%}}</style>
